package com.dsh.v4tune.phoneme;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PushbackInputStream;
import java.util.HashMap;
import java.util.Locale;
import java.util.zip.GZIPInputStream;

/**
 * Hanzi -> toneless pinyin lookup used by {@link ChineseG2P}.
 *
 * <p>The shipped table (assets/dict/pinyin.txt.gz) is generated by
 * tools/gen_pinyin_dict.py from the Unicode Unihan database, kMandarin field,
 * first reading only, tones stripped:
 * <pre>U+6D1B\tluo</pre>
 * The loader also tolerates a literal character in the first column and
 * uncompressed input, so a hand-written table can be dropped in unchanged.
 *
 * <p>Every reading produced by the generator is a toneless pinyin syllable in
 * the ASCII spelling that {@link ChineseG2P#syllableToPhonemes(String)}
 * accepts: u-umlaut is written "v", so U+7EFF gives "lv" and not "lu:".
 */
public final class PinyinDict {

  /** code point -> toneless pinyin (e.g. '\u6D1B' -> "luo"); "v" stands for u-umlaut. */
  static java.util.HashMap<Character,String> DICT = new HashMap<Character,String>(32768);

  private PinyinDict() { }

  /**
   * Loads the gzipped (or plain) dictionary. Never throws: a corrupt or empty
   * stream is reported on stderr and leaves whatever was parsed so far.
   */
  public static void load(InputStream gz) {
    if (gz == null) {
      System.err.println("PinyinDict.load: null stream");
      return;
    }
    InputStream in = gz;
    try {
      PushbackInputStream pin = new PushbackInputStream(gz, 2);
      int b0 = pin.read();
      int b1 = pin.read();
      if (b1 >= 0) pin.unread(b1);
      if (b0 >= 0) pin.unread(b0);
      in = (b0 == 0x1f && b1 == 0x8b) ? new GZIPInputStream(pin, 1 << 16) : pin;
    } catch (IOException e) {
      System.err.println("PinyinDict.load: cannot sniff stream: " + e);
      in = gz;
    }

    HashMap<Character,String> map = new HashMap<Character,String>(32768);
    BufferedReader r = null;
    try {
      r = new BufferedReader(new InputStreamReader(in, "UTF-8"), 1 << 16);
      String line;
      while ((line = r.readLine()) != null) {
        if (line.length() == 0 || line.charAt(0) == '#') continue;
        int tab = line.indexOf('\t');
        char key;
        String py;
        if (tab > 0) {
          String head = line.substring(0, tab).trim();
          py = line.substring(tab + 1).trim();
          if (head.length() >= 2 && (head.charAt(0) == 'U' || head.charAt(0) == 'u') && head.charAt(1) == '+') {
            try {
              int cp = Integer.parseInt(head.substring(2), 16);
              if (cp < 0 || cp > 0xFFFF) continue;      // keys are Java chars
              key = (char) cp;
            } catch (NumberFormatException nfe) {
              continue;
            }
          } else if (head.length() == 1) {
            key = head.charAt(0);                        // literal hanzi column
          } else {
            continue;
          }
        } else if (line.length() >= 2 && line.charAt(0) > 0x7F) {
          key = line.charAt(0);                          // "\u6D1Bluo" style single column
          py = line.substring(1).trim();
        } else {
          continue;
        }
        py = clean(py);
        if (py != null) map.put(Character.valueOf(key), py);
      }
    } catch (IOException e) {
      System.err.println("PinyinDict.load: read failed after " + map.size() + " entries: " + e);
    } catch (RuntimeException e) {
      System.err.println("PinyinDict.load: parse failed after " + map.size() + " entries: " + e);
    } finally {
      try {
        if (r != null) r.close(); else in.close();
      } catch (IOException ignored) { }
    }
    if (map.isEmpty()) {
      System.err.println("PinyinDict.load: dictionary is empty, hanzi lookup disabled");
      return;
    }
    DICT = map;
  }

  /** Keeps only a-z and maps u-umlaut to "v" so the result feeds the G2P parser. */
  private static String clean(String py) {
    if (py == null || py.length() == 0) return null;
    String s = py.trim().toLowerCase(Locale.US);
    int sp = s.indexOf(' ');
    if (sp > 0) s = s.substring(0, sp);                  // first reading only
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c >= 'a' && c <= 'z') sb.append(c);
      else if (c == '\u00fc' || c == 'v') sb.append('v');
      else if (c >= '0' && c <= '9') continue;           // stray tone digit
    }
    return sb.length() == 0 ? null : sb.toString();
  }

  /** Toneless pinyin for a hanzi, or null when the character is not in the table. */
  public static String lookup(char c) {
    return DICT.get(Character.valueOf(c));
  }

  /** Number of loaded characters. */
  public static int size() {
    return DICT.size();
  }

  /** true when a table has been loaded. */
  public static boolean isLoaded() {
    return !DICT.isEmpty();
  }
}
